init:
try{sessionStorage.setItem('ft:intro-seen','1')}catch(e){}
window.__submits=0;
if(window.GPUQueue){const s=GPUQueue.prototype.submit;GPUQueue.prototype.submit=function(){window.__submits++;return s.apply(this,arguments)}}
window.__t0=performance.now();
window.__canvas=()=>document.querySelector('.work-ground-box canvas');
window.__waitGround=async(ms)=>{const t=performance.now();while(performance.now()-t<(ms||12000)&&!window.__canvas())await new Promise(r=>setTimeout(r,25));return window.__canvas()};
window.__ground=()=>{const c=window.__canvas(),f=document.querySelector('.work-ground-fade'),b=document.querySelector('.work-ground-box');const r=b&&b.getBoundingClientRect();return{canvas:!!c,backing:c&&[c.width,c.height],boxCss:r&&[Math.round(r.width),Math.round(r.height)],shown:f&&f.dataset.shown,k:f&&f.style.getPropertyValue('--ground-k'),dpr:devicePixelRatio,screenCss:[innerWidth,innerHeight],pixelsPerScreenCssPx:c&&+(c.width/innerWidth).toFixed(3)}};
window.__frames=(ms)=>new Promise(res=>{let last=0,max=0,over20=0,n=0;const t0=performance.now();const tick=t=>{if(last){const d=t-last;n++;if(d>max)max=d;if(d>20)over20++}last=t;if(t-t0<ms)requestAnimationFrame(tick);else res(JSON.stringify({frames:n,maxGap:Math.round(max*10)/10,over20}))};requestAnimationFrame(tick)});
window.__submitsOver=(ms)=>new Promise(res=>{const a=window.__submits;setTimeout(()=>res(window.__submits-a),ms)});
window.__bare=(on)=>{for(const s of ['.work-stage','[data-row-open]','.wall-page']){document.querySelectorAll(s).forEach(e=>e.style.visibility=on?'hidden':'')}};
window.__fakeHidden=(h)=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>h});Object.defineProperty(document,'visibilityState',{configurable:true,get:()=>h?'hidden':'visible'});document.dispatchEvent(new Event('visibilitychange'))};
